    h, w = len(g), len(g[0])

    # The non-background colored cells define a stamp. Find translated copies
    # whose stamp positions mostly coincide with zero cells, then color those
    # zero cells. Collect placements before painting to avoid interference.
    groups = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0, 4, 9):
                groups.setdefault(g[r][c], []).append((r, c))
    if not groups:
        return g

    color = max(groups, key=lambda x: len(groups[x]))
    pts = groups[color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    placements = []
    threshold = max(3, (len(shape) * 3 + 3) // 4)
    for r in range(h-sh+1):
        for c in range(w-sw+1):
